	return socktmpl.Exclude(selector, value, input)
}

func (f SockaddrFuncs) Include(selector, value string, input sockaddr.IfAddrs) ([]sockaddr.IfAddr, error) {
	return socktmpl.Include(selector, value, input)
}

func (f SockaddrFuncs) Attr(input interface{}, key string) (string, error) {
	if input == nil {
