// SortIfBy is a function that sorts an IfAddrs object based on the given
// selector.  Multiple sort clauses can be passed in as a comma-delimited list
// without whitespace.
func SortIfBy(selectorParam string, inputIfAddrs IfAddrs) (IfAddrs, error) {
	sortedIfs := append(IfAddrs(nil), inputIfAddrs...)
	clauses := strings.Split(selectorParam, ",")
	sortFuncs := make([]sortByIfFunc, len(clauses))
	for i, clause := range clauses {
		switch {
		case strings.HasPrefix(clause, "-"):
			if sf, found := sortFuncsMap[clause[1:]]; found {
				sortFuncs[i] = sortDescIf(sf)
			} else {
				return nil, fmt.Errorf("unknown sort type: %q", clause[1:])
			}
		case strings.HasPrefix(clause, "+"):
			if sf, found := sortFuncsMap[clause[1:]]; found {
				sortFuncs[i] = sf
			} else {
				return nil, fmt.Errorf("unknown sort type: %q", clause[1:])
			}
		default:
			if sf, found := sortFuncsMap[clause]; found {
				sortFuncs[i] = sf
			} else {
